const p = $('Parser').first().json;
const esc = s => String(s ?? '').replace(/([_*[\]`])/g, '\\$1');
const s = $('PFN Build save').first().json;
const name = s.name || 'профиль';
const text = s.mode === 'edit' ? '✅ Профиль обновлён' : '✅ Профиль ' + esc(name) + ' создан и активен';
