const p = $('Parser').first().json;
const rows = $('PFS HTTP read').first().json.rows || [];
const draft = rows[0] ? JSON.parse(rows[0].profile_draft || 'null') : null;
if (!draft || (draft.mode !== 'new' && draft.mode !== 'edit')) return [{ json: { mode: 'invalid' } }];
const step = draft.step;
if (p.callback_action === 'pf_done' && step !== 5 && step !== 6) return [{ json: { mode: 'invalid' } }];
if (step !== 8) draft.step = step + 1;
return [{ json: { mode: 'next', sql: "UPDATE sessions SET profile_draft = ?, updated_at = datetime('now') WHERE tg_user_id = ?", params: [JSON.stringify(draft), p.tg_user_id] } }];

const p = $('Parser').first().json;
const rows = $('PD HTTP state').first().json.rows || [];
const state = (rows[0] && rows[0].state) || 'IDLE';
let draft = null;
try { draft = rows[0] ? JSON.parse(rows[0].profile_draft || 'null') : null; } catch (e) { draft = null; }
if (state === 'PROFILE_AWAIT' && draft && draft.step === 6) return [{ json: { mode: 'interview_doc' } }];
if (state === 'PROFILE_DOCS_SUBMITTING') return [{ json: { mode: 'processing' } }];
if (state === 'PROFILE_ADD_DOC') return [{ json: { mode: 'add_doc' } }];
return [{ json: { mode: 'outside' } }];

const p = $('Parser').first().json;
const rows = $('PD HTTP draft').first().json.rows || [];
const draft = rows[0] ? JSON.parse(rows[0].profile_draft || 'null') : null;
const res = $('PD HTTP bridge').first().json || {};
const name = String(res.name || p.args.file_name || 'документ');
const mime = String(res.mime || '');
const text = String(res.text || '');
const chars = Number(res.chars) || 0;
if (res.error) {
  const updFail = draft
    ? { sql: "UPDATE sessions SET state = 'PROFILE_AWAIT', profile_draft = ?, updated_at = datetime('now') WHERE tg_user_id = ?", params: [JSON.stringify(draft), p.tg_user_id] }
    : { sql: "UPDATE sessions SET state = 'PROFILE_ADD_DOC', profile_draft = NULL, updated_at = datetime('now') WHERE tg_user_id = ?", params: [p.tg_user_id] };
  return [{ json: Object.assign({ mode: 'fail', ok: false, text: '⚠️ Не смог обработать документ: ' + String(res.error) }, updFail) }];
}
if (draft && Array.isArray(draft.docs)) {
  draft.docs.push({ name: name, mime: mime, text: text, chars: chars });
  return [{ json: Object.assign({ mode: 'ok', ok: true, name: name, chars: chars }, { sql: "UPDATE sessions SET state = 'PROFILE_AWAIT', profile_draft = ?, updated_at = datetime('now') WHERE tg_user_id = ?", params: [JSON.stringify(draft), p.tg_user_id] }) }];
}
let docsArr = [];
let clientId = null;
try {
  const dr = $('PD HTTP docs').first().json.rows || [];
  if (dr[0]) {
    const parsed = JSON.parse(dr[0].context_docs || '[]');
    if (Array.isArray(parsed)) docsArr = parsed;
    clientId = dr[0].id;
  }
} catch (e) { docsArr = []; }
docsArr.push({ name: name, mime: mime, text: text, chars: chars });
const updClients = { sql: "UPDATE clients SET context_docs = ?, updated_at = datetime('now') WHERE id = ?", params: [JSON.stringify(docsArr), clientId] };
const updSessions = { sql: "UPDATE sessions SET state = 'PROFILE_ADD_DOC', profile_draft = NULL, updated_at = datetime('now') WHERE tg_user_id = ?", params: [p.tg_user_id] };
return [{ json: Object.assign({ mode: 'ok', ok: true, name: name, chars: chars, add_doc: true }, updClients) }, { json: updSessions }];

