const p = $('Parser').first().json;
const c = $('PFE Check').first().json.client || {};
let audience = '';
try {
  const a = typeof c.audience_json === 'string' ? JSON.parse(c.audience_json) : (c.audience_json || {});
  if (a && a.raw) audience = String(a.raw);
  else if (a && (a.type || a.segments || a.decision_makers)) {
    const bits = [];
    if (a.type) bits.push('Тип: ' + String(a.type));
    if (a.segments) bits.push('Сегменты: ' + (Array.isArray(a.segments) ? a.segments.join(', ') : String(a.segments)));
    if (a.decision_makers) bits.push('ЛПР: ' + (Array.isArray(a.decision_makers) ? a.decision_makers.join(', ') : String(a.decision_makers)));
    audience = bits.join('; ');
  }
} catch (e) { audience = ''; }
let links = [];
try { const l = JSON.parse(c.context_links || '[]'); if (Array.isArray(l)) links = l; } catch (e) { links = []; }
let docs = [];
try { const d = JSON.parse(c.context_docs || '[]'); if (Array.isArray(d)) docs = d; } catch (e) { docs = []; }
let refs = '';
try { const r = JSON.parse(c.context_refs || '[]'); if (Array.isArray(r)) refs = r.join('\n'); } catch (e) { refs = ''; }
const draft = { mode: 'edit', client_id: c.id, step: 1, answers: { name: c.name || '', niche: c.niche || '', description: c.description || '', audience: audience, tone: c.tone || '' }, links: links, docs: docs, refs: refs };
return [{ json: { sql: "UPDATE sessions SET state = 'PROFILE_AWAIT', profile_draft = ?, updated_at = datetime('now') WHERE tg_user_id = ?", params: [JSON.stringify(draft), p.tg_user_id] } }];

