const p = $('Parser').first().json;
const raw = String(p.raw || '').trim();
if (!raw) return [{ json: { ok: false, text: '❌ Пришли ссылку (http/https)' } }];
const urls = raw.split('\n').map(s => s.trim()).filter(Boolean).filter(l => /^https?:\/\//i.test(l));
if (!urls.length) return [{ json: { ok: false, text: '❌ Только ссылки (http/https)' } }];
const rows = $('PAL HTTP read').first().json.rows || [];
let links = [];
try { const parsed = JSON.parse((rows[0] && rows[0].context_links) || '[]'); if (Array.isArray(parsed)) links = parsed; } catch (e) { links = []; }
urls.forEach(u => links.push(u));
return [{ json: { ok: true, links: links, added: urls.length } }];

